// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAnnotations The comments on one target, or on a project
	// (GET /v1/annotations)
	ListAnnotations(w http.ResponseWriter, r *http.Request, params ListAnnotationsParams)
	// CreateAnnotation Comment on a clip, a render or a version of a timeline
	// (POST /v1/annotations)
	CreateAnnotation(w http.ResponseWriter, r *http.Request)
	// DeleteAnnotation Delete a comment
	// (DELETE /v1/annotations/{id})
	DeleteAnnotation(w http.ResponseWriter, r *http.Request, id AnnotationIdPath)
	// UpdateAnnotation Edit, resolve or reopen a comment
	// (PATCH /v1/annotations/{id})
	UpdateAnnotation(w http.ResponseWriter, r *http.Request, id AnnotationIdPath)
	// ListAssets List the workspace's assets, newest first
	// (GET /v1/assets)
	ListAssets(w http.ResponseWriter, r *http.Request, params ListAssetsParams)
	// CreateAsset Start an upload
	// (POST /v1/assets)
	CreateAsset(w http.ResponseWriter, r *http.Request)
	// DeleteAsset Delete an asset
	// (DELETE /v1/assets/{id})
	DeleteAsset(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// GetAsset One asset
	// (GET /v1/assets/{id})
	GetAsset(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// UpdateAsset Edit an asset's title
	// (PATCH /v1/assets/{id})
	UpdateAsset(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// CompleteAssetUpload Finish an upload
	// (POST /v1/assets/{id}/complete)
	CompleteAssetUpload(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// PresignAssetParts Presigned URLs for more parts
	// (POST /v1/assets/{id}/parts)
	PresignAssetParts(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// GetAssetSpriteVtt The hover-scrub thumbnails track, with working URLs
	// (GET /v1/assets/{id}/sprite.vtt)
	GetAssetSpriteVtt(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// GetAssetTranscript The words spoken in an asset, with timings and speech structure
	// (GET /v1/assets/{id}/transcript)
	GetAssetTranscript(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// AbortAssetUpload Abort an upload
	// (DELETE /v1/assets/{id}/upload)
	AbortAssetUpload(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// GetAssetUpload The state of an upload, to resume it
	// (GET /v1/assets/{id}/upload)
	GetAssetUpload(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// GetLibrarySummary Counts of the workspace's library
	// (GET /v1/library/summary)
	GetLibrarySummary(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user, the active workspace and its plan
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListProjects List the workspace's projects, newest first
	// (GET /v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// CreateProject Start a project
	// (POST /v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject Delete a project
	// (DELETE /v1/projects/{id})
	DeleteProject(w http.ResponseWriter, r *http.Request, id ProjectIdPath)
	// GetProject One project, with its footage and current timeline version
	// (GET /v1/projects/{id})
	GetProject(w http.ResponseWriter, r *http.Request, id ProjectIdPath)
	// StartEdit Start an editor run on the project
	// (POST /v1/projects/{id}/edit)
	StartEdit(w http.ResponseWriter, r *http.Request, id ProjectIdPath)
	// ListRenders The renders of a project, newest first
	// (GET /v1/projects/{id}/renders)
	ListRenders(w http.ResponseWriter, r *http.Request, id ProjectIdPath, params ListRendersParams)
	// CreateRender Render a version of the project's timeline
	// (POST /v1/projects/{id}/renders)
	CreateRender(w http.ResponseWriter, r *http.Request, id ProjectIdPath)
	// ListTimelineVersions The versions of a project's timeline, newest first
	// (GET /v1/projects/{id}/timelines)
	ListTimelineVersions(w http.ResponseWriter, r *http.Request, id ProjectIdPath, params ListTimelineVersionsParams)
	// ApplyTimelineOps Edit the timeline with ops (a manual tweak, or the editor agent's tool)
	// (POST /v1/projects/{id}/timelines)
	ApplyTimelineOps(w http.ResponseWriter, r *http.Request, id ProjectIdPath)
	// GetTimelineVersion One version of a project's timeline, with its spec and validation issues
	// (GET /v1/projects/{id}/timelines/{version})
	GetTimelineVersion(w http.ResponseWriter, r *http.Request, id ProjectIdPath, version int)
	// GetRender One render, with its progress and, once ready, presigned URLs for its files
	// (GET /v1/renders/{id})
	GetRender(w http.ResponseWriter, r *http.Request, id RenderIdPath)
	// GetRun A run, with its cost and a summary of its events
	// (GET /v1/runs/{id})
	GetRun(w http.ResponseWriter, r *http.Request, id RunIdPath, params GetRunParams)
	// GetRunArtifacts The artifacts of a run, with their full data
	// (GET /v1/runs/{id}/artifacts)
	GetRunArtifacts(w http.ResponseWriter, r *http.Request, id RunIdPath, params GetRunArtifactsParams)
	// CancelRun Cancel a run
	// (POST /v1/runs/{id}/cancel)
	CancelRun(w http.ResponseWriter, r *http.Request, id RunIdPath)
	// ReplyToRun Answer a question of a run that waits for input
	// (POST /v1/runs/{id}/reply)
	ReplyToRun(w http.ResponseWriter, r *http.Request, id RunIdPath)
	// ResetStyle Forget the creator's style
	// (DELETE /v1/style)
	ResetStyle(w http.ResponseWriter, r *http.Request)
	// GetStyle The creator's style
	// (GET /v1/style)
	GetStyle(w http.ResponseWriter, r *http.Request)
	// UpdateStyle Set the creator's settings
	// (PUT /v1/style)
	UpdateStyle(w http.ResponseWriter, r *http.Request)
	// RemoveStyleReference Remove a reference video
	// (DELETE /v1/style/references/{id})
	RemoveStyleReference(w http.ResponseWriter, r *http.Request, id AssetIdPath)
	// RelearnStyle Learn the style again from the reference videos
	// (POST /v1/style/relearn)
	RelearnStyle(w http.ResponseWriter, r *http.Request)
	// GetWorkspacePlan The plan of the active workspace and what it includes
	// (GET /v1/workspace/plan)
	GetWorkspacePlan(w http.ResponseWriter, r *http.Request)
}

